def verify_langford(seq, n):
    if len(seq) != 2 * n:
        return False

    positions = {}
    for i, val in enumerate(seq):
        if val < 1 or val > n:
            return False
        if val not in positions:
            positions[val] = []
        positions[val].append(i)

    for val in range(1, n + 1):
        if val not in positions or len(positions[val]) != 2:
            return False
        p1, p2 = positions[val]
        if p2 - p1 != val + 1:
            return False
    return True

